import pytest
from shopcart.catalog import Catalog, Product, UnknownProductError, OutOfStockError

def test_status_transitions():
    c = Catalog()
    c.add_product(Product("A1", "Widget", 10.0), 5)
    c.set_status("A1", "discontinued")
    assert c.get("A1").status == "discontinued"
    c.set_status("A1", "archived")
    assert c.get("A1").status == "archived"
    c.set_status("A1", "archived") # No-op
    assert c.get("A1").status == "archived"

def test_invalid_status_raises():
    c = Catalog()
    c.add_product(Product("A1", "Widget", 10.0))
    with pytest.raises(ValueError):
        c.set_status("A1", "invalid")

def test_unknown_sku_status():
    c = Catalog()
    with pytest.raises(UnknownProductError):
        c.set_status("NONEXISTENT", "archived")

def test_discontinued_rules():
    c = Catalog()
    c.add_product(Product("A1", "Widget", 10.0), 5)
    c.set_status("A1", "discontinued")
    with pytest.raises(RuntimeError):
        c.restock("A1", 1)
    assert c.take("A1", 2) == 3

def test_archived_rules():
    c = Catalog()
    c.add_product(Product("A1", "Widget", 10.0), 5)
    c.set_status("A1", "archived")
    with pytest.raises(RuntimeError):
        c.restock("A1", 1)
    assert c.take("A1", 5) == 0
    with pytest.raises(OutOfStockError):
        c.take("A1", 1)

def test_active_behavior():
    c = Catalog()
    c.add_product(Product("A1", "Widget", 10.0), 5)
    assert c.restock("A1", 5) == 10
    assert c.take("A1", 2) == 8
